import{_ as a,o as t,c as s,ao as n}from"./chunks/framework.sSVCmcJS.js";const u=JSON.parse('{"title":"Explanation","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/index.md","filePath":"explanation/index.md","lastUpdated":null}'),o={name:"explanation/index.md"};function i(r,e,h,d,l,c){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="Explanation" tabindex="-1">Explanation <a class="header-anchor" href="#Explanation" aria-label="Permalink to &quot;Explanation {#Explanation}&quot;">​</a></h1><p>These pages state why CesiumLink is shaped the way it is: the split between the browser and the Julia process, what a window guarantees about entity identity, what a module is, and what arrays cost on the wire. They carry opinion, and they name the designs that lost.</p><p>Nothing here is a set of instructions. To build a first scene, read the <a href="./../tutorials/">tutorials</a>. To solve a problem in hand, read the <a href="./../how-to/">how-to guides</a>. The <a href="./../reference/">reference</a> states what each function, each type and each wire field does.</p><h2 id="The-pages" tabindex="-1">The pages <a class="header-anchor" href="#The-pages" aria-label="Permalink to &quot;The pages {#The-pages}&quot;">​</a></h2><ul><li><p><a href="./architecture">The shape of the system</a> — the payload-opaque Core, the Julia process that decides everything, and the line between them.</p></li><li><p><a href="./windows">Windows, keyframes and identity</a> — the declared range against the delivered buffer, what an index means inside one window, and the two push kinds.</p></li><li><p><a href="./server-authoritative">Why the server decides</a> — a control reports input and changes nothing, the listener chain answers with one command batch, and a reconnecting browser gets its scene back.</p></li><li><p><a href="./modules">Modules, vocabularies and glue</a> — the JavaScript that renders, the Julia types the payloads are built from, and the package that authors the messages.</p></li><li><p><a href="./arrays">Arrays on the wire</a> — why arrays travel as bytes behind a JSON header, and why the protocol has no requests.</p></li><li><p><a href="./glossary">Glossary</a> — every term this documentation uses, one sentence each, with the words to avoid.</p></li></ul><h2 id="Decision-records" tabindex="-1">Decision records <a class="header-anchor" href="#Decision-records" aria-label="Permalink to &quot;Decision records {#Decision-records}&quot;">​</a></h2><p>Each decision that shaped the system has a record of its own, stating the decision, the options that lost, and the consequences. Later records supersede earlier ones, and several carry a Revision that changes part of the original text. Both halves stay in the file.</p><p>The records are notes for the people who work on the repository, and not pages of this site. They live under <code>docs/decisions/</code>, one numbered file each. A page above cites one by number, as <code>ADR-0016</code>.</p>',8)])])}const f=a(o,[["render",i]]);export{u as __pageData,f as default};
